insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério da Justiça e Segurança Pública manterá em grau de sigilo os detalhes das especificações de segurança dos modelos. O acesso será concedido, mediante compromisso de sigilo, aos órgãos de identificação ou a outros órgãos públicos sempre que necessário para expedir o documento ou aferir sua autenticidade.', '["Especificações de segurança em sigilo.","Acesso mediante compromisso de sigilo."]'::jsonb, '["Sigilo mantido pelo Ministério da Justiça e Segurança Pública."]'::jsonb, 'A polícia acessa os detalhes de segurança para verificar documento suspeito, com compromisso de sigilo.', '["Assertiva que torna públicos todos os detalhes de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-7'
