insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As renovações da Carteira de Identidade por decurso de prazo de validade serão realizadas para a atualização dos dados cadastrais e biométricos do titular e consideradas continuidade da primeira expedição. A expedição para alteração ou inclusão de dados biográficos ou biométricos, a pedido do titular, será considerada segunda via.', '["Renovação por validade: continuidade da primeira expedição.","Alteração de dados a pedido do titular: segunda via."]'::jsonb, '["Renovação por prazo NÃO é segunda via; alteração a pedido É segunda via."]'::jsonb, 'Quem muda o nome e emite nova identidade recebe segunda via.', '["Assertiva que considera segunda via toda renovação por prazo erra: ela é continuidade da primeira."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-9'
