insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O nome social será incluído mediante requerimento, nos termos do decreto específico. A inclusão ocorre mediante requerimento escrito e assinado, com a expressão nome social, sem prejuízo da menção ao nome do registro civil e sem exigência de documentação comprobatória. O nome social poderá ser excluído por requerimento escrito. Os requerimentos serão arquivados no órgão expedidor com o histórico de alterações.', '["Inclusão do nome social por requerimento escrito.","Sem exigência de documentos comprobatórios.","Mantém o nome do registro civil.","Exclusão por requerimento escrito.","Arquivamento e histórico no órgão expedidor."]'::jsonb, '["Não se exige documentação para incluir o nome social."]'::jsonb, 'A pessoa trans inclui o nome social na identidade apenas com requerimento.', '["Assertiva que exige laudo para incluir o nome social erra: não há exigência de comprovação."]'::jsonb, '[{"termo":"Nome social","significado":"Nome pelo qual a pessoa se identifica socialmente."}]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O titular poderá requerer a inclusão, na carteira digital, das informações constantes dos documentos de que trata a Lei nº 9.049, de 18 de maio de 1995, com consulta por QR code. Poderá também requerer a inclusão de tipo sanguíneo e fator RH, disposição de doar órgãos em caso de morte e condições específicas de saúde cuja divulgação possa contribuir para preservar sua saúde ou salvar sua vida.', '["Inclusão opcional de documentos e informações na carteira digital.","Tipo sanguíneo e fator RH.","Disposição de doar órgãos.","Condições de saúde relevantes."]'::jsonb, '["Inclusão opcional, a pedido do titular."]'::jsonb, 'O titular inclui o tipo sanguíneo na identidade para emergências.', '["Assertiva que torna obrigatória a inclusão do tipo sanguíneo erra: é a pedido do titular."]'::jsonb, '[]'::jsonb, '["Art. 4º, §7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo de validade da Carteira de Identidade será estabelecido de acordo com a idade do titular no momento da expedição: cinco anos para pessoas de zero a onze anos; dez anos para pessoas de doze anos completos a cinquenta e nove anos; e validade indeterminada para pessoas a partir de sessenta anos.', '["Zero a onze anos: cinco anos de validade.","Doze a cinquenta e nove anos: dez anos de validade.","Sessenta anos ou mais: validade indeterminada."]'::jsonb, '["Faixas: cinco, dez anos e indeterminada."]'::jsonb, 'A identidade de uma pessoa de trinta anos vale dez anos.', '["Assertiva que fixa validade de dez anos para quem tem sessenta anos erra: é indeterminada."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade poderá ter a validade negada em razão da alteração dos dados nela contidos, no ponto específico; da existência de danos no meio físico que comprometam a verificação da autenticidade; da alteração de características físicas do titular que suscitem dúvidas fundadas sobre sua identidade; ou da mudança significativa no gesto gráfico da assinatura. A validade não poderá ser negada pelos dois últimos motivos quando o titular for pessoa enferma ou tiver idade a partir de sessenta anos.', '["Alteração dos dados.","Danos que comprometam a autenticidade.","Mudança física que gere dúvida.","Mudança na assinatura.","Proteção a enfermos e a quem tem sessenta anos ou mais."]'::jsonb, '["Enfermos e pessoas com sessenta anos ou mais: não se nega a validade por mudança física ou da assinatura."]'::jsonb, 'A identidade de um idoso não perde validade por mudança na assinatura.', '["Assertiva que permite negar a validade da identidade do idoso por mudança na assinatura erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-16'
