insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A expedição em papel de segurança será permitida até 1º de março de 2032. Até essa data, a carteira poderá ser expedida em papel ou em cartão de policarbonato, a critério do titular, conforme a disponibilidade no ente federativo. A renovação será para o modelo em papel, salvo se o ente encerrar antes. O ente poderá encerrar a expedição em papel em prazo anterior. A emissão para quem já possui o documento em formato anterior é considerada primeira emissão.', '["Papel de segurança permitido até 1º de março de 2032.","Titular escolhe entre papel e policarbonato, conforme disponibilidade.","Ente pode encerrar o papel antes.","Emissão para quem já tem documento antigo é primeira emissão."]'::jsonb, '["Prazo final do papel: 1º de março de 2032."]'::jsonb, 'Até 2032 o titular pode optar entre papel e cartão, se o Estado oferecer.', '["Assertiva que proíbe o papel de segurança desde 2024 erra: ele é permitido até 1º de março de 2032."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
